/* passes */
1. collect_native()      -> ["Stdio", "Math"]
2. collect_extern()      -> []
3. collect_register()    -> []
4. pp_process()          -> macro-expanded text
5. gcl_lex()             -> GclTokenList
6. gcl_parse()           -> GclProgram (AST)
7. gcl_run_program()     -> executes

