/* pass 1 — declarations are registered first */
for each top-level statement:
    if kind is FUNC_DECL, TYPEDEF, ENUM or STRUCT_DECL:
        exec_stmt(...)

/* pass 2 — real code runs */
for each top-level statement:
    if kind is a declaration: skip
    exec_stmt(...)

